def regex_search(pattern: str, text: str) -> bool:
    class Parser:
        def __init__(self, p: str):
            self.p = p
            self.n = len(p)
            self.pos = 0

        def parse(self):
            ast = self.parse_alternative()
            if self.pos != self.n:
                raise ValueError("unmatched parenthesis")
            return ast

        def parse_alternative(self):
            seqs = [self.parse_sequence()]
            while self.pos < self.n and self.p[self.pos] == "|":
                self.pos += 1
                seqs.append(self.parse_sequence())
            if len(seqs) == 1:
                return seqs[0]
            return ("alt", seqs)

        def parse_sequence(self):
            items = []
            while self.pos < self.n:
                c = self.p[self.pos]
                if c == "|" or c == ")":
                    break
                if c == "*" or c == "+" or c == "?":
                    raise ValueError("quantifier without a preceding element")
                items.append(self.parse_term())
            return ("seq", items)

        def parse_term(self):
            c = self.p[self.pos]

            if c == "(":
                self.pos += 1
                child = self.parse_alternative()
                if self.pos >= self.n or self.p[self.pos] != ")":
                    raise ValueError("unclosed group")
                self.pos += 1
                base = ("group", child)

            elif c == "[":
                base = self.parse_class()

            elif c == ".":
                self.pos += 1
                base = ("dot",)

            elif c == "\\":
                self.pos += 1
                if self.pos >= self.n:
                    raise ValueError("trailing backslash")
                base = ("char", self.p[self.pos])
                self.pos += 1

            elif c == "^" or c == "$":
                self.pos += 1
                base = ("assert", c)

            else:
                self.pos += 1
                base = ("char", c)

            if self.pos < self.n and self.p[self.pos] in ("*", "+", "?"):
                if base[0] == "assert":
                    raise ValueError("quantifier on an assertion")
                q = self.p[self.pos]
                self.pos += 1
                base = ("rep", base, q)

            return base

        def parse_class(self):
            self.pos += 1  # consume [
            neg = False
            if self.pos < self.n and self.p[self.pos] == "^":
                neg = True
                self.pos += 1

            ranges = []
            closed = False

            while self.pos < self.n:
                if self.p[self.pos] == "]":
                    closed = True
                    break

                x = self.read_class_char()

                if (
                    x != "-"
                    and self.pos < self.n
                    and self.p[self.pos] == "-"
                    and self.pos + 1 < self.n
                    and self.p[self.pos + 1] != "]"
                ):
                    y = self.read_class_char()
                    if x > y:
                        raise ValueError("invalid character class range")
                    ranges.append((x, y))
                else:
                    ranges.append((x, x))

            if not closed:
                raise ValueError("unclosed character class")
            if not ranges:
                raise ValueError("empty character class")

            self.pos += 1  # consume ]
            return ("class", (neg, ranges))

        def read_class_char(self):
            if self.p[self.pos] == "\\":
                self.pos += 1
                if self.pos >= self.n:
                    raise ValueError("trailing backslash in character class")
                c = self.p[self.pos]
                self.pos += 1
                return c

            c = self.p[self.pos]
            self.pos += 1
            return c

    class Compiler:
        def __init__(self):
            self.epsilon = []
            self.consume = []

        def add_state(self):
            self.epsilon.append([])
            self.consume.append([])
            return len(self.epsilon) - 1

    def compile_node(node, compiler):
        kind = node[0]

        if kind == "seq":
            items = node[1]
            if not items:
                s = compiler.add_state()
                e = compiler.add_state()
                compiler.epsilon[s].append((e, 0))
                return s, e

            start, end = compile_node(items[0], compiler)
            for item in items[1:]:
                ns, ne = compile_node(item, compiler)
                compiler.epsilon[end].append((ns, 0))
                end = ne
            return start, end

        if kind == "alt":
            fragments = [compile_node(item, compiler) for item in node[1]]
            s = compiler.add_state()
            e = compiler.add_state()
            for fs, fe in fragments:
                compiler.epsilon[s].append((fs, 0))
                compiler.epsilon[fe].append((e, 0))
            return s, e

        if kind == "group":
            return compile_node(node[1], compiler)

        if kind == "char":
            s = compiler.add_state()
            e = compiler.add_state()
            compiler.consume[s].append((0, node[1], e))
            return s, e

        if kind == "dot":
            s = compiler.add_state()
            e = compiler.add_state()
            compiler.consume[s].append((1, None, e))
            return s, e

        if kind == "class":
            s = compiler.add_state()
            e = compiler.add_state()
            compiler.consume[s].append((2, node[1], e))
            return s, e

        if kind == "assert":
            s = compiler.add_state()
            e = compiler.add_state()
            condition = 1 if node[1] == "^" else 2
            compiler.epsilon[s].append((e, condition))
            return s, e

        if kind == "rep":
            child_start, child_end = compile_node(node[1], compiler)
            quantifier = node[2]
            s = compiler.add_state()
            e = compiler.add_state()

            if quantifier == "*":
                compiler.epsilon[s].append((child_start, 0))
                compiler.epsilon[s].append((e, 0))
                compiler.epsilon[child_end].append((child_start, 0))
                compiler.epsilon[child_end].append((e, 0))

            elif quantifier == "+":
                compiler.epsilon[s].append((child_start, 0))
                compiler.epsilon[child_end].append((child_start, 0))
                compiler.epsilon[child_end].append((e, 0))

            else:  # quantifier == "?"
                compiler.epsilon[s].append((child_start, 0))
                compiler.epsilon[s].append((e, 0))
                compiler.epsilon[child_end].append((e, 0))

            return s, e

        raise ValueError("internal compiler error")

    def class_match(cls, ch):
        neg, ranges = cls
        if neg:
            for lo, hi in ranges:
                if lo <= ch <= hi:
                    return False
            return True
        for lo, hi in ranges:
            if lo <= ch <= hi:
                return True
        return False

    def epsilon_closure(states, epsilon, pos, text_len):
        visited = set(states)
        stack = list(states)

        while stack:
            state = stack.pop()
            for target, condition in epsilon[state]:
                if (
                    condition == 0
                    or (condition == 1 and pos == 0)
                    or (condition == 2 and pos == text_len)
                ):
                    if target not in visited:
                        visited.add(target)
                        stack.append(target)

        return visited

    def advance(states, consume, ch):
        nxt = set()

        for state in states:
            for kind, payload, target in consume[state]:
                if kind == 0:
                    if ch == payload:
                        nxt.add(target)
                elif kind == 1:
                    nxt.add(target)
                else:
                    if class_match(payload, ch):
                        nxt.add(target)

        return nxt

    ast = Parser(pattern).parse()
    compiler = Compiler()
    start_state, accept_state = compile_node(ast, compiler)

    epsilon = compiler.epsilon
    consume = compiler.consume
    text_len = len(text)

    active = epsilon_closure({start_state}, epsilon, 0, text_len)
    if accept_state in active:
        return True

    for pos, ch in enumerate(text):
        active = epsilon_closure(advance(active, consume, ch) | {start_state}, epsilon, pos + 1, text_len)
        if accept_state in active:
            return True

    return False
